class _ProfilePageState extends State<ProfilePage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<Alignment>(begin: Alignment.centerLeft, end: Alignment.centerRight);

  late final ValueNotifier<AppThemeMode> _themeModeNotifier = ValueNotifier(_settingsRepository.readThemeMode());

  late final StreamSubscription<AppThemeMode> _themeModeSubscription;

  late final AnimationController _alignmentController;
  late Animation<AlignmentGeometry> _alignmentAnimation;

  SettingsRepository get _settingsRepository => context.read<SettingsRepository>();

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _themeModeSubscription = _settingsRepository.themeModeStream.listen(_themeModeNotifier.add);
  }

  @override
  void dispose() {
    _themeModeNotifier.dispose();
    _themeModeSubscription.cancel();
    _alignmentController.dispose();
    super.dispose();
